impl Default for NumberDataSourceContent {
    fn default() -> Self {
        Self::NumberLiteral(NumberLiteral::default())
    }
}

impl crate::Read for NumberDataSourceContent {
    fn other(node: Node) -> Option<Self> {
        Some(Self::Other(node))
    }

    fn read(element: &Element) -> Self {
        match crate::name(element) {
            Some((NS_C, "numLit")) => Self::NumberLiteral(crate::read(element)),
            Some((NS_C, "numRef")) => Self::NumberReference(crate::read(element)),
            _ => Self::Other(Node::Element(element.clone())),
        }
    }
}

impl crate::Write for NumberDataSourceContent {
    fn write_into(&self, writer: &mut crate::Writer<'_, '_>) {
        match self {
            Self::NumberLiteral(arm) => arm.write_into(writer),
            Self::NumberReference(arm) => arm.write_into(writer),
            Self::Other(node) => writer.other(node.clone()),
        }
    }
}

